package mz.bam.seeky.android;
import android.app.*;import java.io.*;import java.nio.file.*;import java.util.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.annotation.*;import static org.junit.Assert.*;

@RunWith(org.robolectric.RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=33,application=Application.class) @LooperMode(LooperMode.Mode.PAUSED)
public class Storage513Test {
    WorkTestSupport w;@Before public void before()throws Exception{w=new WorkTestSupport();}@After public void after(){w.close();}
    File orphan(String text)throws Exception{File file=new File(StudyFileProvider.directory(w.app),"unlinked-"+UUID.randomUUID()+".txt");Files.write(file.toPath(),text.getBytes("UTF-8"));return file;}
    @Test public void cleanupRemovesOnlyExplicitUnreferencedCandidates()throws Exception{long book=w.book("Actual.txt","Texto ligado.");File protectedBook=new File(w.book(book).s("path")),unused=orphan("Órfão");List<File> candidates=StorageReview.unused(w.app);assertTrue(candidates.stream().anyMatch(f->f.equals(unused)));assertFalse(candidates.stream().anyMatch(f->f.equals(protectedBook)));StorageReview.delete(w.app,Arrays.asList(protectedBook,unused),false);assertTrue(protectedBook.exists());assertFalse(unused.exists());}
    @Test public void aRetainedRecoveryProtectsFilesNoLongerInTheCurrentLibrary()throws Exception{long book=w.book("Anterior.txt","Conteúdo anterior.");File file=new File(w.book(book).s("path"));WorkspaceBackup.recovery(w.app,()->false,s->{});try(StudyStore db=new StudyStore(w.app)){db.getWritableDatabase().delete("materials","id=?",new String[]{""+book});}assertFalse(StorageReview.unused(w.app).contains(file));StorageReview.delete(w.app,Collections.singletonList(file),false);assertTrue(file.exists());}
    @Test public void unreadableRecoveryMetadataPreventsDeletion()throws Exception{File unused=orphan("Manter se a verificação falhar.");File dir=new File(w.app.getFilesDir(),"workspace-recovery");dir.mkdirs();Files.write(new File(dir,"broken.zip").toPath(),new byte[]{4,5,6});try{StorageReview.delete(w.app,Collections.singletonList(unused),false);fail();}catch(IOException expected){}assertTrue(unused.isFile());}
    @Test public void pausedJobKeepsItsSourceAndStagedBackupCache()throws Exception{String id=w.job("summary",new JSONObject());File chunk=new File(SummaryWork.root(w.app,id),"source-0.txt");Files.write(chunk.toPath(),"Fonte resumida".getBytes("UTF-8"));File cache=new File(BackupWork.directory(w.app,id),"library.zip");Files.write(cache.toPath(),new byte[]{1});try(TaskStore db=new TaskStore(w.app)){db.add(id,0,"content://source","Trecho",0,0);db.item(id,0,StudyStore.values("target",chunk.getPath()));}assertFalse(StorageReview.unused(w.app).contains(chunk));assertFalse(StorageReview.cache(w.app).contains(cache));}
    @Test public void changingBackgroundDoesNotPruneAnotherBooksSavedBackground()throws Exception{File root=new File(w.app.getFilesDir(),"backgrounds");root.mkdirs();File old=new File(root,UUID.randomUUID()+".audio"),current=new File(root,UUID.randomUUID()+".audio");Files.write(old.toPath(),new byte[]{1});Files.write(current.toPath(),new byte[]{2});String hash=String.join("",Collections.nCopies(64,"e"));BookSettings.update(w.app,hash,data->data.put("profile",new JSONObject().put("background_path",old.getPath())));w.app.getSharedPreferences("reading_background",0).edit().putString("path",current.getPath()).apply();BackgroundSettings.prune(w.app);assertTrue(old.exists());assertTrue(current.exists());}
}
